      leftAngle: leftAngle,
      unexpectedBetweenLeftAngleAndArguments,
      arguments: argumentsBuilder(),
      unexpectedBetweenArgumentsAndRightAngle,
      rightAngle: rightAngle,
      unexpectedAfterRightAngle,
      trailingTrivia: trailingTrivia
    )
  }
}
